<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElButton, ElDialog, ElInput, ElInputNumber, ElOption, ElSelect, ElSwitch, ElTable, ElTableColumn, ElMessage, vLoading } from 'element-plus'
import { httpClient } from '@/shared/http/client'
import type { ApiResponse, Page } from '@/shared/http/create-client'
interface Region {id:number;parentId:number|null;level:number;name:string;code:string;enabled:boolean;sortOrder:number}
const rows=ref<Region[]>([]),page=ref(1),total=ref(0),filterParent=ref(''),loading=ref(false),error=ref(''),dialog=ref(false),editing=ref<number|null>(null)
const form=reactive({parentId:'',level:1,name:'',code:'',enabled:true,sortOrder:0})
async function load(){loading.value=true;error.value='';try{const response=await httpClient.get<ApiResponse<Page<Region>>>('/admin/regions',{params:{page:page.value,size:20,parentId:filterParent.value?Number(filterParent.value):undefined}});rows.value=response.data.data.records;total.value=response.data.data.total}catch(cause){error.value=cause instanceof Error?cause.message:'读取失败'}finally{loading.value=false}}
function open(value?:unknown){const row=value as Region|undefined;editing.value=row?.id??null;Object.assign(form,{parentId:row?.parentId?String(row.parentId):'',level:row?.level??1,name:row?.name??'',code:row?.code??'',enabled:row?.enabled??true,sortOrder:row?.sortOrder??0});dialog.value=true}
async function save(){if(!form.name.trim()||!form.code.trim()){error.value='请填写名称与编码';return}loading.value=true;error.value='';try{const body={parentId:form.parentId?Number(form.parentId):null,level:form.level,name:form.name.trim(),code:form.code.trim(),enabled:form.enabled,sortOrder:form.sortOrder};if(editing.value)await httpClient.put(`/admin/regions/${editing.value}`,body);else await httpClient.post('/admin/regions',body);dialog.value=false;ElMessage.success('区域已保存并审计');await load()}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{loading.value=false}}
onMounted(()=>{void load()})
</script>
<template><div class="work-page"><header class="module-page-head"><p>ADMIN / REGIONS</p><h1>区域管理</h1><span>区域层级与父级由服务端校验；列表按服务端分页。</span></header><section class="admin-surface"><div class="admin-toolbar"><label>父区域 ID <ElInput v-model="filterParent" clearable placeholder="留空查看全部"/></label><ElButton @click="page=1;load()">查询</ElButton><ElButton type="primary" @click="open()">新增区域</ElButton></div><p v-if="error" role="alert" class="error-message">{{ error }} <ElButton @click="load">重试</ElButton></p><ElTable v-loading="loading" :data="rows" empty-text="暂无区域"><ElTableColumn prop="name" label="区域名称" min-width="170"/><ElTableColumn prop="code" label="编码" min-width="130"/><ElTableColumn prop="id" label="ID" width="80"/><ElTableColumn prop="parentId" label="父级 ID" width="100"/><ElTableColumn label="层级" width="90"><template #default="scope">{{ ['','省','市','区县'][scope.row.level] }}</template></ElTableColumn><ElTableColumn prop="sortOrder" label="顺序" width="80"/><ElTableColumn label="状态" width="90"><template #default="scope">{{ scope.row.enabled?'启用':'停用' }}</template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default="scope"><ElButton text @click="open(scope.row)">编辑</ElButton></template></ElTableColumn></ElTable><div class="admin-pager"><ElButton :disabled="loading||page<=1" @click="page--;load()">上一页</ElButton><span>第 {{ page }} 页 · 共 {{ total }} 条</span><ElButton :disabled="loading||page*20>=total" @click="page++;load()">下一页</ElButton></div></section><ElDialog v-model="dialog" :title="editing?'编辑区域':'新增区域'" width="min(520px,calc(100vw - 32px))"><div class="admin-form"><label>名称<ElInput v-model="form.name" maxlength="100"/></label><label>编码<ElInput v-model="form.code" maxlength="32"/></label><label>层级<ElSelect v-model="form.level"><ElOption label="省" :value="1"/><ElOption label="市" :value="2"/><ElOption label="区县" :value="3"/></ElSelect></label><label>父区域 ID（省级留空）<ElInput v-model="form.parentId" inputmode="numeric"/></label><label>排序值<ElInputNumber v-model="form.sortOrder" :min="0"/></label><label>启用<ElSwitch v-model="form.enabled"/></label></div><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="loading" @click="save">保存</ElButton></template></ElDialog></div></template>
